@@ -583,6 +583,126 @@ header {
   justify-content: center;
 }

+.account-hub-account-type-list {
+  display: flex;
+  flex-wrap: wrap;
+  justify-content: center;
+  gap: 20px;
+  margin: 0;
+  padding: 0;
+  border: 0;
+}
+
+.account-hub-account-type-card {
+  position: relative;
+  display: block;
+  inline-size: 148px;
+  block-size: 127px;
+  cursor: pointer;
+  box-shadow: 0 1px 2px rgba(0, 1, 2, 0.1);
+  border-radius: 8px;
+
+  &:has(input:checked) {
+    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.14);
+  }
+
+  & input[type="radio"] {
+    position: absolute;
+    opacity: 0;
+    pointer-events: none;
+  }
+
+  & .account-hub-account-type-card-content {
+    display: grid;
+    grid-template-rows: 56px 69px;
+    box-sizing: border-box;
+    block-size: 100%;
+    overflow: hidden;
+    border: 1px solid var(--color-primary-default);
+    border-radius: 8px;
+  }
+
+  & .account-hub-account-type-card-header {
+    display: flex;
+    flex-direction: column;
+    align-items: center;
+    justify-content: center;
+    gap: 6px;
+    box-sizing: border-box;
+    block-size: 57px;
+    border-radius: 8px 8px 0 0;
+    inline-size: calc(100% + 2px);
+    min-inline-size: 0;
+    padding-inline: 3px;
+    color: var(--color-primary-pressed);
+    background-color: var(--color-primary-soft);
+    font-size: 1.15rem;
+    line-height: 1.1;
+    position: relative;
+    inset-inline-start: -1px;
+    inset-block-start: -1px;
+    text-align: center;
+    overflow-wrap: anywhere;
+  }
+
+  & input[type="radio"]:checked + .account-hub-account-type-card-content .account-hub-account-type-card-header {
+    background-color: var(--color-primary-default);
+    color: var(--color-surface-base);
+  }
+
+  & .account-hub-account-type-card-icon {
+    content: var(--icon-mail);
+    inline-size: 16px;
+    block-size: 16px;
+    flex: 0 0 auto;
+    -moz-context-properties: fill, stroke;
+    fill: rgb(from var(--color-text-brand) r g b / 20%);
+    stroke: currentcolor;
+  }
+
+  & input[type="radio"]:checked + .account-hub-account-type-card-content .account-hub-account-type-card-icon {
+    fill: rgb(from var(--color-surface-base) r g b / 20%);
+  }
+
+  & .account-hub-account-type-card-body {
+    background: var(--color-surface-base);
+    display: grid;
+    place-items: center;
+    border-radius: 0 0 8px 8px;
+    box-sizing: border-box;
+    inline-size: 100%;
+    min-inline-size: 0;
+    padding: 3px;
+    color: var(--color-text-base);
+    font-size: 1rem;
+    text-align: center;
+    font-weight: 400;
+    overflow-wrap: anywhere;
+  }
+
+  & .account-hub-account-type-card-badge {
+    position: absolute;
+    inset-block-start: -10px;
+    inset-inline-start: 50%;
+    transform: translateX(-50%);
+    display: none;
+    padding: 3px 6px;
+    border-radius: 3px;
+    color: var(--color-surface-base);
+    background-color: var(--color-primary-default);
+    font-size: 0.769rem;
+    font-weight: 700;
+    line-height: 1;
+    text-transform: uppercase;
+    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.14);
+    z-index: 1;
+  }
+
+  &.recommended .account-hub-account-type-card-badge {
+    display: block;
+  }
+}
